import type { EmailTemplate } from "./email-templates";

/**
 * Newsletter templates — broadcasts to the whole list, as opposed to the 1:1
 * reply templates in ./email-templates.data.
 *
 * Kept in a separate array on purpose. These carry {{unsubscribe_url}} and
 * {{preferences_url}}, which are signed per recipient at send time; picking one
 * as a reply in the mail composer would produce a broken or, worse, someone
 * else's unsubscribe link.
 *
 * "group" decides where each appears:
 *   digest    — the weekly catalogue email
 *   announce  — fired automatically when content is published or a price drops
 *   broadcast — written by hand in the admin panel
 *   lifecycle — about the subscription itself (welcome, preferences, goodbye)
 */
export type NewsletterGroup = "digest" | "announce" | "broadcast" | "lifecycle";

export type NewsletterTemplate = Omit<EmailTemplate, "category"> & { group: NewsletterGroup };

export const NEWSLETTER_GROUPS: { id: NewsletterGroup; label: string; hint: string }[] = [
  { id: "broadcast", label: "Broadcasts", hint: "Write and send to the list yourself" },
  { id: "digest", label: "Weekly digest", hint: "The what's-available email" },
  { id: "announce", label: "Announcements", hint: "Sent automatically when something changes" },
  { id: "lifecycle", label: "Subscription", hint: "Welcome, preferences, unsubscribe" },
];

